actions.command:
python3 -c "import os, pathlib, textwrap, re; p=pathlib.Path(os.environ['TARGET_DIR'])/'run_buggy.py'; src=p.read_text();
# 1. Add logging, time imports and CONFIG after load_dotenv()
load_pattern=r'load_dotenv\(\)'
addition=textwrap.dedent('''
load_dotenv()

import logging
import time  # for retry backoff

# ENHANCED_PROGRAM_V1: central configuration
CONFIG = {
    "MAX_RETRIES": 3,
    "INITIAL_BACKOFF": 1,  # seconds
    "TOKEN_BUFFER": 200,
    "PERSISTENCE_MAX_ITERS": 5,
}

LOGGER = logging.getLogger(__name__)
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(name)s - %(levelname)s - %(message)s')
''')
src=re.sub(load_pattern, addition, src, count=1);
# 2. Insert retry_decorator after LOGGER definition
logger_pattern=r'LOGGER = logging.getLogger\(__name__\)'
retry_code=textwrap.dedent('''
LOGGER = logging.getLogger(__name__)
# ENHANCED_PROGRAM_V1: retry decorator for transient failures
def retry_decorator(func):
    def wrapper(*args, **kwargs):
        retries = CONFIG["MAX_RETRIES"]
        backoff = CONFIG["INITIAL_BACKOFF"]
        for attempt in range(1, retries + 1):
            try:
                LOGGER.info(f"Attempt {attempt} for {func.__name__}")
                return func(*args, **kwargs)
            except Exception as e:
                LOGGER.warning(f"{func.__name__} failed on attempt {attempt}: {e}")
                if attempt == retries:
                    raise
                time.sleep(backoff)
                backoff *= 2
    return wrapper
''')
src=re.sub(logger_pattern, retry_code, src, count=1);
# 3. Decorate generate_and_store_embeddings
src=re.sub(r'def generate_and_store_embeddings\(', r'@retry_decorator\n\ndef generate_and_store_embeddings(', src, count=1);
# 4. Add logging after persistence
src=src.replace('vectordb.persist()', 'vectordb.persist()\n        LOGGER.info("Embeddings persisted successfully.")');
# 5. Log entry into run_agent
src=src.replace('def run_agent(pdf_path, user_id):', 'def run_agent(pdf_path, user_id):\n    LOGGER.info(f"run_agent called with pdf_path={pdf_path}, user_id={user_id}")');
# Write back
p.write_text(src)
print('Modifications applied')"

